// GENERATED by scripts/libertymd-emergency-pattern-sync.mjs.
// Source of truth: supabase/functions/libertymd-care-proxy/emergency-patterns.ts
const PATTERN_SET_VERSION = "1.0.0";
const rules = [
  {
    "id": "acs_chest_pain",
    "crisis_type": "acs_chest_pain",
    "care_setting": "call_911",
    "message": "These symptoms can be a medical emergency. Call 911 or go to the ER now. Do not drive yourself.",
    "source": "chest (pain|pressure|tightness)|crushing (chest|pressure)|elephant (on|sitting)|pain radiating to (left )?arm|jaw pain.{0,30}(sweat|sweating|nausea)",
    "flags": "i"
  },
  {
    "id": "thunderclap_headache",
    "crisis_type": "thunderclap_headache",
    "care_setting": "call_911",
    "message": "A sudden worst-of-life headache can be an emergency. Call 911 or go to the ER now.",
    "source": "worst headache of (my|his|her) life|thunderclap|sudden(ly)? (severe|worst|excruciating|blinding|intense) headache|headache.{0,25}(came on|hit me|started).{0,15}(suddenly|instantly|out of nowhere)|headache with (neck stiffness|confusion|weakness|vision loss)",
    "flags": "i"
  },
  {
    "id": "anaphylaxis",
    "crisis_type": "anaphylaxis",
    "care_setting": "call_911",
    "message": "This may be anaphylaxis. Use epinephrine if available and call 911 immediately.",
    "source": "throat (is )?tight|lip swelling|tongue swelling|anaphylaxis|cannot breathe after|wheezing after (a )?(peanut|shellfish|bee|sting)",
    "flags": "i"
  },
  {
    "id": "respiratory_distress",
    "crisis_type": "respiratory_distress",
    "care_setting": "call_911",
    "message": "Severe breathing problems need emergency care. Call 911 or go to the ER now.",
    "source": "cannot breathe|can't breathe|blue lips|gasping for air|oxygen (sat|saturation).{0,12}(8\\d|9[0-2])\\b",
    "flags": "i"
  },
  {
    "id": "surgical_abdomen",
    "crisis_type": "surgical_abdomen",
    "care_setting": "call_911",
    "message": "Severe abdominal pain with these features can be a surgical emergency. Seek ER care now.",
    "source": "sudden severe (abdominal|belly|stomach) pain|severe (right lower|lower right|lower) (abdominal|belly|stomach) pain|rigid abdomen|pain (is )?so bad i (can't|cannot) walk",
    "flags": "i"
  },
  {
    "id": "stroke_fast",
    "crisis_type": "stroke_fast",
    "care_setting": "call_911",
    "message": "These symptoms may be a stroke. Call 911 now. Note when they started, and do not drive yourself.",
    "source": "face (is )?(drooping|droopy)|one side of (my|the) (body|face).{0,30}(weak|numb)|arm (is )?(weak|numb).{0,30}(speech|speak)|speech (is )?(slurred|garbled)|cannot speak properly|can't speak properly",
    "flags": "i"
  },
  {
    "id": "suicidal_ideation",
    "crisis_type": "suicidal_ideation",
    "care_setting": "crisis_line",
    "message": "Please call or text 988 now to reach the Suicide & Crisis Lifeline. Stay with a trusted person while you connect.",
    "source": "\\b(i want to kill myself|i (am|'m) going to kill myself|i (want|plan) to end my life|i plan to kill myself|i (have|'ve) been thinking about (ending my life|killing myself|suicide)|i am thinking about suicide|i (am|'m) suicidal)\\b",
    "flags": "i"
  }
];

const body = $('Webhook').first().json.body || $('Webhook').first().json || {};
const message = String(body.message || body.text || '').trim();
const history = Array.isArray(body.history) ? body.history : [];
const patient = body.patient && typeof body.patient === 'object' ? body.patient : {};
const msg = message.toLowerCase();

function firstUnnegatedMatch(rule) {
  const flags = rule.flags.includes('g') ? rule.flags : rule.flags + 'g';
  const matcher = new RegExp(rule.source, flags);
  let match;
  while ((match = matcher.exec(msg)) !== null) {
    const before = msg.slice(Math.max(0, match.index - 40), match.index);
    // Commas do not end a clause: "no lip swelling, tongue swelling, or X"
    // is one negated list. Adversatives do end a clause, preserving
    // "no chest pain but crushing chest pressure".
    const segment = before.split(/[;.!?]|\bbut\b|\bhowever\b|\balthough\b|\bthough\b/i).pop() || '';
    const negated = /\b(no|not|without|denies|denied|never|don'?t have|doesn'?t have)\b/.test(segment);
    const thirdPartyHistory =
      /\b(my|his|her|their)\s+\w*\s*(father|mother|dad|mum|mom|brother|sister|friend|husband|wife|son|daughter|uncle|aunt)\s+(had|has had|used to have)\b/.test(before)
      || /\b(family history|history of|hx of)\b/.test(before);
    if (!negated && !thirdPartyHistory) return match[0];
    if (match.index === matcher.lastIndex) matcher.lastIndex += 1;
  }
  return null;
}

let hit = null;
for (const rule of rules) {
  const matchedSpan = firstUnnegatedMatch(rule);
  if (matchedSpan !== null) {
    hit = rule;
    break;
  }
}

if (hit) {
  return [{
    json: {
      route: 'force_end',
      status: 'force_end',
      risk_level: 'emergency',
      crisis_type: hit.crisis_type,
      force_end: true,
      is_emergency: true,
      care_setting: hit.care_setting,
      message: hit.message,
      red_flags: [hit.crisis_type],
      source: 'deterministic',
      pattern_id: hit.id,
      pattern_set_version: PATTERN_SET_VERSION,
      message_text: message,
      history,
      patient,
    }
  }];
}

return [{
  json: {
    route: 'llm',
    status: 'needs_llm',
    force_end: false,
    is_emergency: false,
    message_text: message,
    history,
    patient,
  }
}];

